func extractProfile(args []string) ([]string, string, int) {
        profile := ""
        remaining := make([]string, 0, len(args))
        i := 0
        for i < len(args) {
                if args[i] == "--profile" {
                        if i+1 >= len(args) {
                                fmt.Fprintln(os.Stderr, "error: --profile requires a profile name")
                                return nil, "", 1
                        }
                        profile = args[i+1]
                        i += 2
                } else if strings.HasPrefix(args[i], "--profile=") {
                        profile = args[i][len("--profile="):]
                        i++
                } else {
                        remaining = append(remaining, args[i])
                        i++
                }
        }
        return remaining, profile, 0
}

