		case allowTargets && strings.HasPrefix(args[i], "--targets="):
			raw := args[i][len("--targets="):]
			i++
			for _, name := range strings.Split(raw, ",") {
				name = strings.TrimSpace(name)
				if name == "" {
					continue
				}
				targets = append(targets, name)
			}
		default:
			remaining = append(remaining, args[i])
			i++
		}
	}
	if allowTargets && len(targets) == 0 {
		targets = nil
	}
	return
}

func targetMap(m *Manifest) map[string]*Target {
	byName := make(map[string]*Target, len(m.Targets))
	for _, t := range m.Targets {
		byName[t.Name] = t
	}
	return byName
}

func topologicalOrderFor(m *Manifest, allowed map[string]bool) ([]*Target, error) {
	order, err := topologicalOrder(m)
	if err != nil {
		return nil, err
	}
	if allowed == nil {
		return order, nil
	}
	filtered := make([]*Target, 0, len(order))
	for _, t := range order {
		if allowed[t.Name] {
			filtered = append(filtered, t)
		}
	}
	return filtered, nil
}

func resolveBuildSet(m *Manifest, names []string) (map[string]bool, error) {
	byName := targetMap(m)
	for _, name := range names {
		if _, ok := byName[name]; !ok {
			return nil, fmt.Errorf("error: unknown target: '%s'", name)
		}
	}

	allowed := make(map[string]bool)
	var visit func(name string)
	visit = func(name string) {
		t, ok := byName[name]
		if !ok || allowed[name] {
			return
		}
		allowed[name] = true
		for _, dep := range t.Deps {
			visit(dep)
		}
	}
	for _, name := range names {
		visit(name)
	}
	return allowed, nil
}

func checkConstraints(m *Manifest, profile string, allowed map[string]bool) error {
	order, err := topologicalOrderFor(m, allowed)
	if err != nil {
		return err
	}
	for _, t := range order {
		if t.Constraints == nil {
			continue
		}
		if len(t.Constraints.RequireProfiles) > 0 {
			ok := false
			for _, p := range t.Constraints.RequireProfiles {
				if p == profile {
					ok = true
					break
				}
			}
			if !ok {
				return fmt.Errorf("error: target '%s' requires profile: %s", t.Name, strings.Join(t.Constraints.RequireProfiles, ", "))
			}
		}
		if len(t.Constraints.IncompatibleProfiles) > 0 {
			for _, p := range t.Constraints.IncompatibleProfiles {
				if p == profile {
					return fmt.Errorf("error: target '%s' incompatible with profile: '%s'", t.Name, p)
				}
			}
		}
	}
	return nil
}

func transitiveDepsInSet(t *Target, byName map[string]*Target, allowed map[string]bool) []string {
	seen := make(map[string]bool)
	var visit func(name string)
	visit = func(name string) {
		dep, ok := byName[name]
		if !ok || !allowed[name] {
			return
		}
		for _, d := range dep.Deps {
			if allowed[d] && !seen[d] {
				seen[d] = true
				visit(d)
			}
		}
	}
	visit(t.Name)
	res := make([]string, 0, len(seen))
	for k := range seen {
		res = append(res, k)
	}
	sort.Strings(res)
	return res
}

func storeObjectDirs(storeRoot string) []string {
	objectsDir := filepath.Join(storeRoot, "objects")
	var dirs []string
	filepath.Walk(objectsDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			dirs = append(dirs, path)
		}
		return nil
	})
	return dirs
}

func storeSize(storeRoot string) int64 {
	objectsDir := filepath.Join(storeRoot, "objects")
	var total int64
	filepath.Walk(objectsDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if !info.IsDir() {
			total += info.Size()
		}
		return nil
	})
	return total
}

func staleEntriesForTarget(storeRoot, name, currentFingerprint string) int {
	var stale int
	for _, dir := range storeObjectDirs(storeRoot) {
		metaPath := filepath.Join(dir, "metadata.json")
		if _, err := os.Stat(metaPath); err != nil {
			continue
		}
		meta, err := readMetadata(metaPath)
		if err != nil {
			continue
		}
		if meta.Name == name && meta.Fingerprint != currentFingerprint {
			stale++
		}
	}
	return stale
}

func cmdStatus(args []string) int {
	args, profile, status := extractProfile(args)
	if status != 0 {
		return status
	}
	if len(args) != 1 {
		fmt.Fprintln(os.Stderr, "error: usage: buildvault status <manifest_path> [--profile <name>]")
		return 1
	}

	m, dir, err := loadManifest(args[0])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
